use mbse_assurance::{*,metrics::{self as m,*},traces::{self,NativeEndpoint}};
use mbse_model::{stage1::*,types::{self as t,Id},extensions::Extensions};
use serde_json::{Value,json};
use std::{collections::{BTreeMap,BTreeSet},path::PathBuf};
fn oracle()->Value{serde_json::from_str(include_str!("../../../docs/parity/p37a/fixtures/expected-counts.json")).unwrap()}
fn original()->Editor{let v:Value=serde_json::from_str(include_str!("../../../docs/parity/p36b/verification/native-02/run/analysis-final-cold-copy.kernspan")).unwrap();Editor::new(serde_json::from_value(v["snapshot"].clone()).unwrap(),"metrics:runtime".into()).unwrap()}
fn fixture()->Editor{
 let mut s=Snapshot::new(DocumentId("metrics:fixed-two-systems".into()));s.extensions=Some(Extensions::default());
 for(id,kind,scope)in[(2,RecordKind::System,2),(3,RecordKind::Mission,1),(4,RecordKind::Capability,2)]{s.records.insert(RecordId(id),Record{id:RecordId(id),kind,name:format!("Independent native #{id}"),scope:RecordId(scope),fields:BTreeMap::new()});}
 let mut st=t::Store::default();for(id,system,kind)in[(10,1,t::Kind::Component),(11,1,t::Kind::Value(t::Scalar::Real)),(14,1,t::Kind::Component),(20,2,t::Kind::Component),(21,2,t::Kind::Value(t::Scalar::Real))]{st.definitions.insert(Id(id),t::Definition{id:Id(id),system:RecordId(system),name:format!("Type #{id}"),kind});}
 for(id,owner,value_type)in[(12,10,11),(22,20,21)]{st.properties.insert(Id(id),t::Property{id:Id(id),owner:Id(owner),name:format!("Property #{id}"),value_type:Id(value_type),multiplicity:t::Multiplicity{lower:1,upper:Some(1)}});}
 st.usages.insert(Id(13),t::Usage{id:Id(13),owner:Id(10),target:Id(14),name:"Fixed Part".into(),kind:t::UsageKind::Part});st.defaults.insert(Id(12),t::values::Literal{kind:t::Scalar::Real,text:"3".into()});s.extensions.as_mut().unwrap().namespaces.insert(t::NAMESPACE.into(),serde_json::to_value(st).unwrap());s.extensions.as_mut().unwrap().required_namespaces.push(t::NAMESPACE.into());s.next_id=23;Editor::new(s,"metrics:small-runtime".into()).unwrap()
}
fn board(e:&Editor)->(Board,RequirementId){
 let mut b=Board::new();let a=b.add_requirement("Supplier".into()).unwrap();let child=b.add_requirement_under("Selected child".into(),Some(a)).unwrap();let c=b.add_requirement("Other supplier".into()).unwrap();let case=b.add_test_case("Documentary case".into(),"Inspect".into(),"Retained output".into()).unwrap();
 for(kind,source,target)in[(TraceKind::Derive,TraceEndpoint::Requirement(child),a),(TraceKind::Refine,TraceEndpoint::Requirement(c),child),(TraceKind::Satisfy,traces::native_endpoint(&e.snapshot,1).unwrap(),child),(TraceKind::Verify,TraceEndpoint::TestCase(case),child)]{b.add_trace(kind,source,target,"Display label only".into(),&e.snapshot).unwrap();}
 let detached=b.add_trace(TraceKind::Satisfy,traces::native_endpoint(&e.snapshot,2).unwrap(),c,"Detached native source".into(),&e.snapshot).unwrap();if let TraceEndpoint::Native(n)=&mut b.register.traces.get_mut(&detached).unwrap().source{n.document="different-document".into();}b.register.unknown.insert("fixture.opaque/1".into(),json!({"raw":"9e","meaning":"not interpreted"}));(b,child)
}
#[test]
fn metrics_original_native_fixture_matches_fixed_independent_family_counts_without_evaluating_invalid_calculations(){
 let e=original();let before=e.snapshot.clone();let r=m::query(&e,None,Scope::default()).unwrap();let o=oracle();assert_eq!(r.model.top_level_records,o["native_top_level_records"].as_u64().unwrap()as usize);assert_eq!(serde_json::to_value(&r.model.native_by_kind).unwrap(),o["native"]);assert_eq!(serde_json::to_value(&r.model.typed).unwrap(),o["typed"]);assert_eq!(r.model.calculation_definitions,16);assert!(r.traces.is_none()&&r.register_source.is_none());assert_eq!(e.snapshot,before);assert!(r.opaque_native_namespaces.contains(&"fixture.p32c.opaque/1".into()));
 let encoded:Value=serde_json::from_slice(&r.encoded().unwrap()).unwrap();assert_eq!(encoded["rules_revision"],RULES_REVISION);assert_eq!(encoded["native_source"]["model_revision"],252);assert_eq!(encoded["native_source"]["raw_version"],516);assert_eq!(encoded["native_source"]["snapshot_hash"],e.snapshot.digest());
}
#[test]
fn metrics_system_scope_uses_exact_native_and_typed_owners_while_requirement_scope_remains_independent(){
 let e=fixture();let(b,_)=board(&e);let all=m::query(&e,Some(&b),Scope::default()).unwrap();assert_eq!(all.model.top_level_records,4);assert_eq!(all.model.typed.as_ref().unwrap()["component_definitions"],3);
 for(system,components,values,parts,defaults)in[(1,2,1,1,1),(2,1,1,0,0)]{let scope=Scope{native:NativeScope::System(RecordId(system)),requirements:RequirementScope::All};let r=m::query(&e,Some(&b),scope).unwrap();assert_eq!(r.model.top_level_records,2);assert_eq!(r.model.native_by_kind["System"],1);assert_eq!(r.model.typed.as_ref().unwrap()["component_definitions"],components);assert_eq!(r.model.typed.as_ref().unwrap()["value_definitions"],values);assert_eq!(r.model.typed.as_ref().unwrap()["properties"],1);assert_eq!(r.model.typed.as_ref().unwrap()["part_usages"],parts);assert_eq!(r.model.typed.as_ref().unwrap()["default_literal_entries"],defaults);assert_eq!(r.traces,all.traces);}
}
#[test]
fn metrics_trace_subset_keeps_boundary_links_separate_and_uses_existing_exact_endpoint_projection(){
 let e=fixture();let(b,child)=board(&e);let before=b.as_value().unwrap();let all=m::query(&e,Some(&b),Scope::default()).unwrap().traces.unwrap();let o=oracle()["trace_oracle"].clone();assert_eq!(all.requirements,3);assert_eq!(all.traces,o["all_traces"].as_u64().unwrap()as usize);assert_eq!(all.active_traces,4);assert_eq!(all.detached_traces,1);let projected=b.trace_projection(&e.snapshot);assert_eq!(all.active_traces,projected.iter().filter(|p|p.active).count());assert_eq!(all.parent_links_within_scope,1);
 let r=m::query(&e,Some(&b),Scope{native:NativeScope::All,requirements:RequirementScope::Selected(BTreeSet::from([child]))}).unwrap().traces.unwrap();assert_eq!(r.requirements,1);assert_eq!(r.traces,2);assert_eq!(r.active_traces,2);assert_eq!(r.detached_traces,0);assert_eq!(r.boundary_traces,2);assert_eq!(r.parent_links_crossing_scope,1);assert_eq!(r.by_kind["Satisfy"],1);assert_eq!(r.by_kind["Verify"],1);assert_eq!(r.documentary_test_cases_referenced,1);assert_eq!(r.evidence_records,0);assert_eq!(b.as_value().unwrap(),before);
}
#[test]
fn metrics_empty_explicit_subset_empty_register_and_absent_register_are_distinct_and_bad_scopes_refuse(){
 let e=fixture();let(b,_)=board(&e);let scope=Scope{native:NativeScope::All,requirements:RequirementScope::Selected(BTreeSet::new())};let r=m::query(&e,Some(&b),scope.clone()).unwrap().traces.unwrap();assert_eq!((r.requirements,r.traces,r.boundary_traces),(0,0,0));assert!(m::query(&e,None,scope).unwrap_err().contains("REGISTER_REQUIRED"));let r=m::query(&e,Some(&Board::new()),Scope::default()).unwrap();assert!(r.register_source.is_some());assert_eq!(r.traces.unwrap().requirements,0);
 assert!(m::query(&e,Some(&b),Scope{native:NativeScope::All,requirements:RequirementScope::Selected((1..=10001).map(RequirementId).collect())}).unwrap_err().contains("SCOPE_LIMIT"));
 assert!(m::query(&e,None,Scope{native:NativeScope::System(RecordId(3)),requirements:RequirementScope::All}).unwrap_err().contains("SYSTEM_SCOPE"));assert!(m::query(&e,Some(&b),Scope{native:NativeScope::All,requirements:RequirementScope::Selected(BTreeSet::from([RequirementId(999)]))}).unwrap_err().contains("SCOPE_MISSING"));
}
#[test]
fn metrics_receipt_freshness_binds_scope_full_native_register_raw_and_runtime_even_with_reused_counters(){
 let mut e=fixture();let(mut b,_)=board(&e);let scope=Scope::default();let r=m::query(&e,Some(&b),scope.clone()).unwrap();let encoded=r.encoded().unwrap();assert!(r.is_current(&e,Some(&b),&scope));let other=Scope{native:NativeScope::System(RecordId(1)),requirements:RequirementScope::All};assert!(!r.is_current(&e,Some(&b),&other));let foreign=Editor::new(e.snapshot.clone(),"other-runtime".into()).unwrap();assert!(!r.is_current(&foreign,Some(&b),&scope));assert!(!r.is_current(&e,None,&scope));let previous=b.register.drafts.insert("new:statement".into(),mbse_assurance::RawDraft{text:"Unapplied raw".into(),valid:false});assert!(!r.is_current(&e,Some(&b),&scope));if let Some(old)=previous{b.register.drafts.insert("new:statement".into(),old);}else{b.register.drafts.remove("new:statement");}assert!(r.is_current(&e,Some(&b),&scope));e.snapshot.records.get_mut(&RecordId(3)).unwrap().name="Same counters changed source".into();assert!(!r.is_current(&e,Some(&b),&scope));assert_eq!(r.encoded().unwrap(),encoded);
}
#[test]
fn metrics_malformed_or_unsupported_sources_refuse_without_partial_zero_counts_or_model_register_mutation(){
 let mut e=fixture();let(mut b,_)=board(&e);b.register.next_id=0;let before=b.register.clone();assert!(m::query(&e,Some(&b),Scope::default()).is_err());assert_eq!(b.register,before);e.snapshot.extensions.as_mut().unwrap().namespaces.insert(t::NAMESPACE.into(),json!({"profile":"future.types/999","schema_version":999,"unrecognized":"retain exact"}));let before=e.snapshot.clone();assert!(m::query(&e,None,Scope::default()).is_err());assert_eq!(e.snapshot,before);
}
#[test]
fn metrics_shared_native_projection_keeps_document_identity_expected_kind_and_label_semantics_exact(){
 let e=fixture();let(mut b,_)=board(&e);let source=b.register.traces.values_mut().find(|t|matches!(t.source,TraceEndpoint::Native(ref n)if n.id==1)).unwrap();source.label="Verify Passed".into();source.source=TraceEndpoint::Native(NativeEndpoint{document:e.snapshot.document_id.0.clone(),id:1,expected:t::tags::TargetKind::ComponentDefinition});let projected=b.trace_projection(&e.snapshot);let r=m::query(&e,Some(&b),Scope::default()).unwrap().traces.unwrap();assert_eq!(r.active_traces,3);assert_eq!(r.detached_traces,2);assert_eq!(r.detached_traces,projected.iter().filter(|p|!p.active).count());assert_eq!(r.by_kind["Satisfy"],2);assert_eq!(r.by_kind["Verify"],1);
}
#[test]
fn metrics_native_bound_cold_recovery_and_export_keep_entire_snapshot_eight_maps_and_historical_report_exact(){
 use mbse_model::{stage1_io::{Session,execute_write},native_views::{self as v,Views},native_views_io as io};let area=tempfile::tempdir_in(std::env::var_os("TMPDIR").unwrap()).unwrap();let path=PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../docs/parity/p36b/verification/native-02/run/analysis-final-cold-copy.kernspan");let mut session=Session::open(area.path(),&path).unwrap();let before=session.editor.snapshot.clone();let report=m::query(&session.editor,None,Scope::default()).unwrap();let source=std::fs::read(path.with_file_name("analysis-final-cold-copy.mbse-views.json")).unwrap();let mut doc:v::Document=serde_json::from_slice(&source).unwrap();doc.profile=v::scenarios::RECOVERY_PROFILE.into();doc.binding=None;let views=Views::restore(&doc.encoded().unwrap(),&session.editor).unwrap();let copy=area.path().join("metrics.kernspan");let job=session.begin_save(&copy).unwrap();assert!(session.complete(execute_write(job)));let side=area.path().join("metrics.mbse-views.json");let mut writer=io::Io::default();let job=writer.begin(&session,&views,&side,io::Kind::Bound).unwrap();assert!(writer.complete(&session,&views,io::execute(job)));let cold=Session::open(area.path(),&copy).unwrap();assert_eq!(cold.editor.snapshot,before);assert!(!report.is_current(&cold.editor,None,&Scope::default()));let decoded=Views::decode(&std::fs::read(&side).unwrap(),&cold.editor,&cold.native_checkpoint().unwrap().unwrap()).unwrap();let a=serde_json::to_value(views.document()).unwrap();let b=serde_json::to_value(decoded.document()).unwrap();for map in["views","occurrences","edges","typed_ports","connector_edges","activity_diagrams","state_machine_diagrams","scenario_diagrams"]{assert_eq!(a[map],b[map]);}let export=area.path().join("metrics.json");std::fs::write(&export,report.encoded().unwrap()).unwrap();let data:Value=serde_json::from_slice(&std::fs::read(export).unwrap()).unwrap();assert_eq!(data["rules_revision"],RULES_REVISION);assert_eq!(data["native_source"]["model_revision"],252);assert_eq!(session.editor.snapshot,before);
}

#[test]
fn metrics_legacy_native_counts_do_not_require_migration_and_typed_unavailable_keeps_existing_trace_projection(){
 let typed=fixture();let(b,_)=board(&typed);let mut source=typed.snapshot.clone();source.extensions=None;let e=Editor::new(source,"legacy-metrics-runtime".into()).unwrap();let before=e.snapshot.clone();let r=m::query(&e,Some(&b),Scope::default()).unwrap();assert_eq!(r.model.top_level_records,4);assert!(r.model.typed.is_none());let p=b.trace_projection(&e.snapshot);let counts=r.traces.as_ref().unwrap();assert_eq!(counts.active_traces,3);assert_eq!(counts.detached_traces,2);assert_eq!(counts.active_traces,p.iter().filter(|p|p.active).count());assert_eq!(e.snapshot,before);assert_eq!(serde_json::from_slice::<Value>(&r.encoded().unwrap()).unwrap()["model"]["typed"],Value::Null);
 let blank=Editor::new(Snapshot::new(DocumentId("fresh-legacy".into())),"fresh-legacy-runtime".into()).unwrap();let r=m::query(&blank,None,Scope::default()).unwrap();assert_eq!(r.model.top_level_records,1);assert!(r.model.typed.is_none()&&r.traces.is_none());assert!(blank.snapshot.extensions.is_none());
}

#[test]
fn metrics_parent_links_crossing_scope_count_both_selected_child_and_selected_parent_directions(){
 let e=fixture();let(b,child)=board(&e);let before=b.as_value().unwrap();for id in[RequirementId(1),child]{let scope=Scope{native:NativeScope::All,requirements:RequirementScope::Selected(BTreeSet::from([id]))};let t=m::query(&e,Some(&b),scope).unwrap().traces.unwrap();assert_eq!(t.parent_links_within_scope,0);assert_eq!(t.parent_links_crossing_scope,1,"selected #{} must disclose its accepted containment edge leaving or entering the subset",id.0);if id==RequirementId(1){assert_eq!(t.traces,0);assert_eq!(t.boundary_traces,1);}}assert_eq!(b.as_value().unwrap(),before);
}
